-- 0007_reference_data: the values behind every drop-down, filter and list.
--
-- One table holds every reference set. A row has a stable `code` (what
-- clients send and what other tables store), a `label` (what people read),
-- a sort order and an `active` flag. The API returns only active rows and
-- validates input against the same rows, so a market administrator can
-- rename, reorder, add or retire a value without a code release (BR-001).
--
-- Markets are not a set here: they keep their own table.
CREATE TABLE reference_items (
    set_code              text NOT NULL CONSTRAINT reference_items_set_check CHECK (set_code IN (
                              'deal_types', 'property_categories', 'property_types', 'request_types', 'contact_methods',
                              'account_roles', 'directory_kinds', 'service_trades', 'cities', 'suburbs', 'listing_features')),
    code                  text NOT NULL CONSTRAINT reference_items_code_length CHECK (char_length(code) BETWEEN 1 AND 80),
    label                 text NOT NULL,
    -- Directory kinds: "Estate agency" next to the plural label "Estate agencies".
    singular_label        text,
    description           text,
    sort_order            integer NOT NULL DEFAULT 0,
    active                boolean NOT NULL DEFAULT true,
    -- NULL = applies to every market. Cities and suburbs are per market.
    market_id             uuid REFERENCES markets (id),
    -- A property type's category; a suburb's city.
    parent_code           text,
    -- Account roles: the heading they are listed under on the sign-up form.
    group_code            text,
    group_label           text,
    group_sort_order      integer,
    -- Account roles: true = choosing it only records a request (PENDING_VERIFICATION).
    requires_verification boolean,
    created_at            timestamptz NOT NULL DEFAULT now(),
    updated_at            timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (set_code, code),
    -- Defence in depth: a platform administrator role can never be stored as
    -- a selectable account role. The API also refuses them before it looks here.
    CONSTRAINT reference_items_no_platform_roles CHECK (
        set_code <> 'account_roles'
        OR code NOT IN ('SUPER_ADMIN', 'PLATFORM_ADMIN', 'MARKET_ADMIN', 'FINANCE_ADMIN', 'CONTENT_ADMIN', 'MODERATOR', 'SUPPORT'))
);
CREATE INDEX reference_items_listing_idx ON reference_items (set_code, sort_order, label) WHERE active;
CREATE INDEX reference_items_parent_idx ON reference_items (set_code, parent_code) WHERE parent_code IS NOT NULL;

-- The vocabularies below were fixed lists in CHECK constraints. They are now
-- rows in reference_items and are validated by the API, so the constraints
-- that would block a new value are removed. Account roles keep a database
-- guard against platform roles.
ALTER TABLE property_requests DROP CONSTRAINT property_requests_type_check;
ALTER TABLE property_requests DROP CONSTRAINT property_requests_contact_method_check;
ALTER TABLE business_enquiries DROP CONSTRAINT business_enquiries_contact_method_check;
ALTER TABLE directory_profiles DROP CONSTRAINT directory_profiles_kind_check;
ALTER TABLE user_account_roles DROP CONSTRAINT user_account_roles_role_check;
ALTER TABLE user_account_roles ADD CONSTRAINT user_account_roles_no_platform_roles CHECK (
    role NOT IN ('SUPER_ADMIN', 'PLATFORM_ADMIN', 'MARKET_ADMIN', 'FINANCE_ADMIN', 'CONTENT_ADMIN', 'MODERATOR', 'SUPPORT'));

